wi=openpyxl.load_workbook(inp, data_only=False)
wo=openpyxl.load_workbook(out, data_only=False)
wg=openpyxl.load_workbook(gold, data_only=False)

# Style comparison helpers
def style_tuple(c):
    if c.has_style:
        s=c._style
        return (s.numFmtId, s.fontId, s.fillId, s.borderId, s.alignment.horizontal if s.alignment else None, s.alignment.vertical if s.alignment else None, s.protection is not None)
    return None

# Ensure every cell present in input has matching style in output
diffs=[]
for wsname in wi.sheetnames:
    ws_i=wi[wsname]; ws_o=wo[wsname]
    for row in ws_i.iter_rows():
        for c in row:
            co=c.coordinate
            o=ws_o[co]
            si=style_tuple(c); so=style_tuple(o)
            if si!=so:
                diffs.append((wsname,co,si,so,repr(c.value),repr(o.value)))
print('style diffs count:', len(diffs))
for d in diffs[:50]:
    print(d)

# Verify all 60 formulas match golden exactly
diff_f=[]
for wsname in ['Sales','Product List','Purchases','Inventory']:
    for row in wg[wsname].iter_rows():
        for c in row:
            if isinstance(c.value,str) and c.value.startswith('='):
                ov=wo[wsname][c.coordinate].value
                if ov!=c.value:
                    diff_f.append((wsname,c.coordinate,c.value,ov))
