# Verify all cells values equal golden
diff_v=[]
for wsname in ['Sales','Product List','Purchases','Inventory']:
    for row in wg[wsname].iter_rows():
        for c in row:
            ov=wo[wsname][c.coordinate].value
            if ov!=c.value:
                diff_v.append((wsname,c.coordinate,repr(c.value),repr(ov)))
print('value diffs vs golden:', len(diff_v))
for d in diff_v[:30]: print(d)
